#include <stdio.h>

static int depth = 0, max_depth = 0;

static void recurse(int limit) {
    depth++;
    if (depth > max_depth) max_depth = depth;
    if (depth < limit) recurse(limit);
    depth--;
}

int main(void) {
    recurse(1000);
    printf("递归 1000 层：max_depth = %d\n", max_depth);
    printf("每个栈帧含返回地址+保存寄存器+局部变量，约几十到几百字节\n");
    printf("Linux 默认栈 8MB 约可支撑几万层；Windows 默认约 1MB，更浅\n");
    printf("深度由用户输入决定时，必须改显式栈（堆上，可判空可限深）\n");
    return 0;
}
